insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_73_v1'
from (values
('127.489.d.1.A',3,'In a busy clinic, the staff member who takes vital signs, rooms patients, and assists the provider with exams is the:','["medical assistant", "radiologist", "pharmacist", "surgeon"]'::jsonb,0,'Medical assistants support clinical care.','original'),
('127.489.d.1.A',4,'A medical assistant may work in settings such as physician offices, urgent care centers, and:','["airports", "outpatient clinics", "restaurants", "stadiums"]'::jsonb,1,'MAs work in ambulatory settings.','original'),
('127.489.d.1.B',3,'Tasks a medical assistant is legally allowed to perform are defined by the state''s:','["lunch policy", "parking map", "scope of practice", "dress code"]'::jsonb,2,'Scope of practice sets limits.','original'),
('127.489.d.1.B',4,'A medical assistant who is asked to interpret a patient''s lab results and diagnose a condition should decline because this is outside the:','["lunch hour", "break schedule", "uniform policy", "scope of practice"]'::jsonb,3,'Diagnosis belongs to licensed providers.','original'),
('127.489.d.1.C',3,'In the healthcare hierarchy, a medical assistant reports to a supervising physician or:','["clinic manager", "vendor", "visitor", "patient"]'::jsonb,0,'Chain of command guides authority.','original'),
('127.489.d.1.C',4,'Following the chain of command means that a concern about patient care is first brought to the:','["insurance company", "immediate supervisor", "neighbor", "newspaper"]'::jsonb,1,'Use proper channels.','original'),
('127.489.d.1.D',3,'A group of professionals such as nurses, therapists, and physicians who work together to plan patient care is an interdisciplinary:','["store", "parade", "team", "band"]'::jsonb,2,'Teams combine expertise.','original'),
('127.489.d.1.D',4,'A dietitian on an interdisciplinary team contributes by planning the patient''s:','["surgery schedule", "billing codes", "parking", "nutrition"]'::jsonb,3,'Each member has a role.','original'),
('127.489.d.2.A',3,'When a patient''s blood pressure reading is much higher than normal, the medical assistant should report it to the provider both orally and in:','["writing", "a cartoon", "a song", "a text to a friend"]'::jsonb,0,'Abnormal findings are documented.','original'),
('127.489.d.2.A',4,'When reporting an abnormal result, the medical assistant should state the patient''s name, the finding, and the:','["clinic''s address", "time it was taken", "lunch order", "coat color"]'::jsonb,1,'Include time and facts.','original'),
('127.489.d.2.B',3,'Speaking at a slow pace in simple words to a patient with limited health knowledge helps with:','["billing", "confusion", "understanding", "delay"]'::jsonb,2,'Clear communication aids understanding.','original'),
('127.489.d.2.B',4,'Repeating back what a patient says to confirm the meaning is a technique called:','["assuming", "interrupting", "ignoring", "active listening"]'::jsonb,3,'Active listening verifies meaning.','original'),
('127.489.d.2.C',3,'A patient who is upset about a long wait should be met with calm, respectful words and:','["an apology", "blame", "laughter", "silence"]'::jsonb,0,'Empathy defuses frustration.','original'),
('127.489.d.2.C',4,'A patient who does not make eye contact because of cultural norms should be treated with:','["suspicion", "respect", "teasing", "impatience"]'::jsonb,1,'Cultural sensitivity matters.','original'),
('127.489.d.2.D',3,'Two coworkers disagree about covering a shift. A cooperative way to resolve it is to find a solution that works for:','["nobody", "the loudest voice", "both people", "only the boss"]'::jsonb,2,'Cooperation seeks mutual solutions.','original'),
('127.489.d.2.D',4,'A conflict-resolution technique where each side gives up something to reach agreement is:','["denial", "competition", "avoidance", "compromise"]'::jsonb,3,'Compromise is mutual concession.','original'),
('127.489.d.2.E',3,'A medical assistant explaining the importance of washing hands to prevent the flu is providing patient:','["education", "coding", "billing", "scheduling"]'::jsonb,0,'Patient education improves health.','original'),
('127.489.d.2.E',4,'After teaching a patient how to use an inhaler, the medical assistant checks understanding by asking the patient to:','["leave quickly", "demonstrate it back", "guess", "sign a form only"]'::jsonb,1,'Teach-back confirms learning.','original'),
('127.489.d.3.A',3,'The ethical principle of doing no harm is called:','["autonomy", "justice", "non-maleficence", "beneficence"]'::jsonb,2,'First, do no harm.','original'),
('127.489.d.3.A',4,'Treating all patients fairly regardless of income or background reflects the principle of:','["fidelity", "autonomy", "beneficence", "justice"]'::jsonb,3,'Justice means fairness.','original'),
('127.489.d.3.B',3,'Cloning, genetic testing, and electronic data sharing raise ethical questions about technology and patient:','["privacy", "advertising", "parking", "fashion"]'::jsonb,0,'Technology creates ethical issues.','original'),
('127.489.d.3.B',4,'A debate on whether insurance companies should use a person''s genetic test results raises concerns of:','["entertainment", "discrimination", "transportation", "decoration"]'::jsonb,1,'Genetic information can be misused.','original'),
('127.489.d.3.C',3,'Failing to provide the standard of care that results in injury to a patient is:','["delegation", "courtesy", "malpractice", "donation"]'::jsonb,2,'Malpractice is negligence by a professional.','original'),
('127.489.d.3.C',4,'One element that must be proven in a negligence case is that the provider owed the patient a:','["vacation", "gift", "discount", "duty of care"]'::jsonb,3,'Duty is the first element.','original'),
('127.489.d.3.D',3,'A document listing a patient''s rights to respect, privacy, and informed decisions is the Patient''s:','["Bill of Rights", "Menu", "Directory", "Calendar"]'::jsonb,0,'The Patient''s Bill of Rights.','original'),
('127.489.d.3.D',4,'The law that protects patient health information from being shared without permission is:','["OSHA", "HIPAA", "ADA", "CLIA"]'::jsonb,1,'HIPAA protects privacy.','original'),
('127.489.d.4.A',3,'When scheduling a new patient, the medical assistant considers the provider''s availability and how long the visit will:','["rain", "change", "take", "sell"]'::jsonb,2,'Visit length determines slot size.','original'),
('127.489.d.4.A',4,'A patient who needs a procedure that takes 60 minutes should be scheduled in a(n):','["walk-in queue only", "lunch break", "standard 10-minute slot", "extended appointment slot"]'::jsonb,3,'Match slot to need.','original'),
('127.489.d.4.B',3,'Double-booking two patients at the same time can lead to long:','["wait times", "lunches", "holidays", "vacations"]'::jsonb,0,'Overbooking causes delays.','original'),
('127.489.d.4.B',4,'Leaving a gap in the schedule for unexpected urgent visits is called building in a(n):','["menu", "buffer", "parade", "salary"]'::jsonb,1,'Buffers absorb surprises.','original'),
('127.489.d.4.C',3,'The code that describes the patient''s condition on an insurance claim is the:','["dress code", "area code", "diagnosis code", "zip code"]'::jsonb,2,'Diagnosis codes report why care was needed.','original'),
('127.489.d.4.C',4,'The amount a clinic charges for a service before insurance adjustments is called the:','["premium", "deductible", "copay", "billed charge"]'::jsonb,3,'Billed charge is the listed fee.','original'),
('127.489.d.4.D',3,'Completing patient registration includes recording the patient''s demographics, insurance, and:','["emergency contact", "favorite color", "shoe size", "hobbies"]'::jsonb,0,'Registration collects key data.','original'),
('127.489.d.4.D',4,'A new patient is asked to sign a consent form and a privacy notice during:','["discharge", "registration", "lab testing", "imaging"]'::jsonb,1,'Forms are signed at registration.','original'),
('127.489.d.4.E',3,'The federal insurance program for people age 65 and older is:','["CHIP", "TRICARE", "Medicare", "Medicaid"]'::jsonb,2,'Medicare covers older adults.','original'),
('127.489.d.4.E',4,'Insurance for people with low income that is run jointly by states and the federal government is:','["Medicare", "TRICARE", "COBRA", "Medicaid"]'::jsonb,3,'Medicaid is income-based.','original'),
('127.489.d.4.F',3,'An insurance card shows the plan name, group number, and the member:','["ID number", "weight", "blood type", "favorite doctor"]'::jsonb,0,'Cards identify coverage.','original'),
('127.489.d.4.F',4,'The fixed dollar amount shown on an insurance card that a patient pays for an office visit is the:','["deductible", "copay", "coinsurance", "premium"]'::jsonb,1,'The copay is a flat fee.','original'),
('127.489.d.4.G',3,'Approval required from an insurer before certain procedures are covered is called prior:','["registration", "vaccination", "authorization", "examination"]'::jsonb,2,'Prior authorization is pre-approval.','original'),
('127.489.d.4.G',4,'A list of drugs that a health plan covers is its:','["glossary", "itinerary", "directory", "formulary"]'::jsonb,3,'Formularies list covered medications.','original'),
('127.489.d.4.H',3,'A digital version of a patient''s chart used by providers is an electronic:','["health record", "phone book", "photo album", "bank account"]'::jsonb,0,'EHRs store charts.','original'),
('127.489.d.4.H',4,'Components of an EHR include patient demographics, problem lists, medication lists, and:','["timecards", "lab results", "menus", "parking logs"]'::jsonb,1,'EHRs hold clinical data.','original'),
('127.489.d.4.I',3,'A benefit of an EHR is that records can be accessed quickly by authorized staff, while a risk is the possibility of a:','["longer lunch", "paper jam", "data breach", "new carpet"]'::jsonb,2,'EHRs raise security risks.','original'),
('127.489.d.4.I',4,'A system that lets patients view their own test results online is a benefit of an EHR called a patient:','["drawer", "bulletin board", "tray", "portal"]'::jsonb,3,'Portals improve access.','original'),
('127.489.d.5.A',3,'A medical assistant charts that a rash is on the front surface of the torso. The directional term for the front side is:','["anterior", "distal", "superior", "posterior"]'::jsonb,0,'Anterior = front.','original'),
('127.489.d.5.A',4,'Cutting the body from head to toe into a right half and a left half follows which anatomical plane?','["transverse plane", "sagittal plane", "oblique plane", "coronal plane"]'::jsonb,1,'Sagittal divides left and right.','original'),
('127.489.d.5.B',3,'The medical term for the study of the heart is:','["nephrology", "neurology", "cardiology", "dermatology"]'::jsonb,2,'Cardio = heart.','original'),
('127.489.d.5.B',4,'The term ''tachycardia'' means a heart rate that is:','["too slow", "irregular only", "absent", "too fast"]'::jsonb,3,'Tachy = fast.','original'),
('127.489.d.5.C',3,'In the word ''nephritis,'' the root ''nephr'' refers to the:','["kidney", "lung", "liver", "stomach"]'::jsonb,0,'Nephr = kidney.','original'),
('127.489.d.5.C',4,'In ''arthroscopy,'' the suffix ''-scopy'' means:','["removal", "visual examination", "repair", "inflammation"]'::jsonb,1,'-scopy = looking.','original'),
('127.489.d.6.A',3,'At the start of a visit, the medical assistant asks the patient the main reason for the visit, which is called the chief:','["insurer", "order", "complaint", "billing"]'::jsonb,2,'CC states the reason.','original'),
('127.489.d.6.A',4,'During an intake interview, the medical assistant documents current medications, allergies, and the patient''s:','["car", "favorite music", "hobbies", "medical history"]'::jsonb,3,'History informs care.','original'),
('127.489.d.6.B',3,'A medical chart helps identify patient care needs by showing the patient''s history, previous visits, and:','["treatment plan", "parking pass", "phone plan", "hairstyle"]'::jsonb,0,'The chart is the record of care.','original'),
('127.489.d.6.B',4,'The part of a chart that lists the provider''s orders is the:','["menu", "physician''s orders", "billing statement", "visitor log"]'::jsonb,1,'Orders direct care.','original'),
('127.489.d.6.C',3,'A normal resting adult heart rate is typically between 60 and:','["20 beats per minute", "300 beats per minute", "100 beats per minute", "200 beats per minute"]'::jsonb,2,'60 to 100 bpm.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
