select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_73_v1'
from (values
('127.489.d.6.C',4,'A normal adult respiratory rate at rest is about:','["80 breaths per minute", "2 to 4 breaths per minute", "40 to 60 breaths per minute", "12 to 20 breaths per minute"]'::jsonb,3,'12 to 20 breaths/min.','original'),
('127.489.d.6.D',3,'When taking a manual blood pressure, the first sound heard through the stethoscope is the:','["systolic pressure", "mean pressure", "pulse pressure", "diastolic pressure"]'::jsonb,0,'First Korotkoff sound = systolic.','original'),
('127.489.d.6.D',4,'The blood pressure cuff should be placed on the arm so that its lower edge is about an inch above the:','["shoulder", "antecubital space", "wrist", "elbow tip"]'::jsonb,1,'Cuff placement affects accuracy.','original'),
('127.489.d.6.E',3,'A baby''s head circumference, length, and weight are examples of:','["lab tests", "billing codes", "anthropometric measurements", "vital signs only"]'::jsonb,2,'Anthropometric means body measurements.','original'),
('127.489.d.6.E',4,'To measure an adult''s height accurately, the patient should stand straight with the heels together and:','["leaning forward", "shoes on", "sitting down", "shoes off"]'::jsonb,3,'Remove shoes.','original'),
('127.489.d.6.F',3,'A patient weighs 176 pounds. In kilograms (1 kg = 2.2 lb) this is:','["80 kg", "40 kg", "387 kg", "176 kg"]'::jsonb,0,'176 / 2.2 = 80.','original'),
('127.489.d.6.F',4,'A patient is 5 feet 10 inches tall. In inches this is:','["58 inches", "70 inches", "60 inches", "510 inches"]'::jsonb,1,'5 x 12 + 10 = 70.','original'),
('127.489.d.7.A',3,'Testing performed at or near the site of patient care, with results available quickly, is called point of:','["view", "entry", "care testing", "sale"]'::jsonb,2,'POCT is bedside testing.','original'),
('127.489.d.7.A',4,'An advantage of point of care testing is that the provider receives results during the:','["next year", "next month", "week after discharge", "same visit"]'::jsonb,3,'Quick results.','original'),
('127.489.d.7.B',3,'A urine specimen collected after cleaning the genital area and discarding the first portion is a clean-catch:','["midstream sample", "timed sample", "fasting sample", "random sample"]'::jsonb,0,'Midstream reduces contamination.','original'),
('127.489.d.7.B',4,'A throat swab for strep is collected from the back of the throat and the:','["cheeks", "tonsils", "tongue tip", "lips"]'::jsonb,1,'Swab the tonsillar area.','original'),
('127.489.d.7.C',3,'A test performed in a medical office to measure the glucose level using a drop of blood is a point of care:','["MRI", "X-ray", "glucose test", "EKG"]'::jsonb,2,'Fingerstick glucose.','original'),
('127.489.d.7.C',4,'A rapid test that can be done in the office to check for influenza uses a:','["biopsy", "blood transfusion", "bone scan", "nasal swab"]'::jsonb,3,'Rapid flu tests use swabs.','original'),
('127.489.d.7.D',3,'A Snellen eye chart is used to screen a patient''s:','["visual acuity", "balance", "blood pressure", "hearing"]'::jsonb,0,'The chart tests distance vision.','original'),
('127.489.d.7.D',4,'For a Snellen test, a patient normally stands at a distance of:','["100 feet", "20 feet", "2 feet", "50 feet"]'::jsonb,1,'20 feet is standard.','original'),
('127.489.d.7.E',3,'A 12-lead EKG records the heart''s:','["temperature", "oxygen level", "electrical activity", "blood sugar"]'::jsonb,2,'EKG measures electrical signals.','original'),
('127.489.d.7.E',4,'Lead V1 on a 12-lead EKG is placed in the fourth intercostal space to the right of the:','["navel", "spine", "armpit", "sternum"]'::jsonb,3,'V1 lies right of the sternum.','original'),
('127.489.d.8.A',3,'The six rights of medication administration include right patient, right drug, right dose, right route, right time, and right:','["documentation", "flavor", "brand", "price"]'::jsonb,0,'Document after giving.','original'),
('127.489.d.8.A',4,'Before giving any medication, a medical assistant checks the label against the order three times, which helps confirm the right:','["pen", "drug", "color of the room", "lunch"]'::jsonb,1,'Label checks prevent errors.','original'),
('127.489.d.8.B',3,'A drug that lowers fever and relieves mild pain is classified as an:','["diuretic only", "anticoagulant", "analgesic and antipyretic", "antibiotic only"]'::jsonb,2,'Acetaminophen is both.','original'),
('127.489.d.8.B',4,'Amoxicillin is classified as an antibiotic and its indication is the treatment of:','["high blood pressure", "diabetes", "viral infections", "bacterial infections"]'::jsonb,3,'Antibiotics treat bacteria.','original'),
('127.489.d.8.C',3,'An unintended and harmful response to a medicine is an adverse:','["event", "order", "label", "dose"]'::jsonb,0,'Adverse events must be reported.','original'),
('127.489.d.8.C',4,'The desired beneficial effect of a medicine on the patient is called its therapeutic:','["brand", "response", "failure", "wall"]'::jsonb,1,'Therapeutic effect is the intended one.','original'),
('127.489.d.8.D',3,'A provider orders 250 mg and the vial contains 125 mg per mL. The amount to give is:','["0.5 mL", "4 mL", "2 mL", "1 mL"]'::jsonb,2,'250 / 125 = 2.','original'),
('127.489.d.8.D',4,'An order is 0.5 g and the tablets are 250 mg each. The number of tablets needed is:','["0.5 tablet", "1 tablet", "4 tablets", "2 tablets"]'::jsonb,3,'0.5 g = 500 mg; 500 / 250 = 2.','original'),
('127.489.d.8.E',3,'Before giving a medication, the medical assistant asks the patient about known:','["allergies", "hobbies", "vacations", "birthdays"]'::jsonb,0,'Allergy checks prevent reactions.','original'),
('127.489.d.8.E',4,'A drug that should not be given because it could harm a patient with a certain condition has a(n):','["indication", "contraindication", "dosage", "brand"]'::jsonb,1,'Contraindications mean avoid.','original'),
('127.489.d.8.F',3,'A medication that is placed between the cheek and the gum is given by the:','["rectal route", "intravenous route", "buccal route", "topical route"]'::jsonb,2,'Buccal = cheek.','original'),
('127.489.d.8.F',4,'A drug given under the tongue is given by the sublingual route, while a drug injected into a muscle is given by the:','["topical route", "oral route", "inhalation route", "intramuscular route"]'::jsonb,3,'IM = into muscle.','original'),
('127.489.d.8.G',3,'Before drawing up a medication from a vial, the medical assistant should clean the rubber stopper with:','["an alcohol wipe", "soap", "a dry tissue", "a paper towel"]'::jsonb,0,'Disinfect stoppers.','original'),
('127.489.d.8.G',4,'To draw up medication from an ampule, the medical assistant uses a filter needle to avoid drawing up:','["labels", "glass particles", "air bubbles only", "water"]'::jsonb,1,'Filter needles catch glass.','original'),
('127.489.d.8.H',3,'A subcutaneous injection is given into the tissue just below the:','["muscle", "bone", "skin", "vein"]'::jsonb,2,'Subcutaneous means under the skin.','original'),
('127.489.d.8.H',4,'An injection given at a 90-degree angle is typically an:','["subcutaneous injection at 15 degrees", "oral dose", "intradermal injection", "intramuscular injection"]'::jsonb,3,'IM injections go in at 90 degrees.','original'),
('127.489.d.8.I',3,'A common site for an intramuscular injection in the upper arm is the:','["deltoid", "trapezius", "forearm", "biceps tendon"]'::jsonb,0,'Deltoid is used for small volumes.','original'),
('127.489.d.8.I',4,'The ventrogluteal and vastus lateralis are also sites for:','["blood pressure checks", "intramuscular injections", "vision screening", "EKG leads"]'::jsonb,1,'These are large muscles.','original'),
('127.489.d.8.J',3,'The amount of medication to be injected, the patient''s age, and muscle mass all help determine the injection:','["price", "brand", "site", "color"]'::jsonb,2,'Site selection depends on volume and patient.','original'),
('127.489.d.8.J',4,'Small muscles such as the deltoid should hold no more than about 1 mL, so larger volumes are given in a:','["tendon", "bone", "smaller vein", "larger muscle"]'::jsonb,3,'Volume limits site.','original'),
('127.489.d.8.K',3,'In needle sizes, a higher gauge number means a needle that is:','["thinner", "thicker", "longer", "shorter"]'::jsonb,0,'Higher gauge = smaller diameter.','original'),
('127.489.d.8.K',4,'A thick, viscous medication would be drawn up with a needle that has a(n):','["colored cap only", "lower gauge number", "shorter handle", "higher gauge number"]'::jsonb,1,'Thicker fluids need wider needles.','original'),
('127.489.d.8.L',3,'A 1 mL syringe used for small doses has markings in tenths and:','["inches", "pounds", "hundredths of a milliliter", "gallons"]'::jsonb,2,'Tuberculin syringes are finely marked.','original'),
('127.489.d.8.L',4,'An insulin syringe is marked in:','["milliliters only", "grains", "ounces", "units"]'::jsonb,3,'Insulin is measured in units.','original'),
('127.489.d.9.A',3,'A blood specimen that needs to be kept cold should be stored in:','["a refrigerator or cooler", "a hot car", "sunlight", "a drawer by the heater"]'::jsonb,0,'Storage affects accuracy.','original'),
('127.489.d.9.A',4,'A specimen being sent to an outside lab is placed in a sealed biohazard bag to prevent:','["rust", "leaks and exposure", "fading", "noise"]'::jsonb,1,'Transport safety.','original'),
('127.489.d.9.B',3,'In the order of draw, the first tube collected is usually the blood culture bottle or the:','["lavender top", "gray top", "light blue top", "green top"]'::jsonb,2,'Light blue (citrate) comes early.','original'),
('127.489.d.9.B',4,'Following the order of draw is important because additives from one tube can contaminate the next and change:','["label size", "needle length", "tube color only", "test results"]'::jsonb,3,'Carryover alters results.','original'),
('127.489.d.9.C',3,'A tube with EDTA used for a complete blood count has a:','["lavender top", "gray top", "green top", "red top"]'::jsonb,0,'Lavender = EDTA.','original'),
('127.489.d.9.C',4,'A gray-top tube, which contains sodium fluoride, is commonly used for testing:','["cultures", "blood glucose", "clotting time", "electrolytes"]'::jsonb,1,'Gray tops preserve glucose.','original'),
('127.489.d.9.D',3,'The vein most often used for a routine blood draw is in the:','["neck", "ankle", "antecubital area", "palm"]'::jsonb,2,'Median cubital vein is common.','original'),
('127.489.d.9.D',4,'The vein located in the middle of the antecubital area and most often chosen for venipuncture is the median:','["aorta", "femoral vein", "jugular vein", "cubital vein"]'::jsonb,3,'It is large and stable.','original'),
('127.489.d.9.E',3,'Before inserting the needle, the tourniquet is placed above the site and should be left on for no longer than:','["one minute", "an hour", "five minutes", "ten minutes"]'::jsonb,0,'Prolonged tourniquet use alters results.','original'),
('127.489.d.9.E',4,'After the needle is removed, pressure is applied to the puncture site with gauze to stop:','["movement", "bleeding", "speaking", "itching"]'::jsonb,1,'Post-procedure care.','original'),
('127.489.d.9.F',3,'Tube labels should include the patient''s full name, date of birth, date and time, and the collector''s:','["phone", "address of the clinic", "initials", "favorite food"]'::jsonb,2,'Labels identify the sample.','original'),
('127.489.d.9.F',4,'A specimen should be labeled in the presence of the:','["visitor", "receptionist", "pharmacist", "patient"]'::jsonb,3,'Label at bedside to avoid mix-ups.','original'),
('127.489.d.10.A',3,'According to Erikson, the stage of life when a person focuses on identity and independence is:','["adolescence", "infancy", "old age", "toddlerhood"]'::jsonb,0,'Adolescence centers on identity.','original'),
('127.489.d.10.A',4,'Toddlers developing independence is the stage that psychologists call autonomy versus:','["integrity and despair", "shame and doubt", "trust and mistrust", "identity confusion"]'::jsonb,1,'Erikson''s second stage.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_73_v1'
from (values
('127.489.d.10.B',3,'A patient who denies a diagnosis even after being told it is using the defense mechanism of:','["bargaining", "humor", "denial", "acceptance"]'::jsonb,2,'Denial is protective.','original'),
('127.489.d.10.B',4,'A patient who lashes out at staff because of fear about a diagnosis may be using a coping mechanism called:','["humor", "sublimation only", "acceptance", "displacement"]'::jsonb,3,'Displacement redirects emotion.','original'),
('127.489.d.10.C',3,'A legal document that states a person''s wishes about medical treatment if they cannot speak for themselves is an advance:','["directive", "schedule", "receipt", "invoice"]'::jsonb,0,'Advance directives guide care.','original'),
('127.489.d.10.C',4,'A person chosen to make health care decisions for a patient who cannot is a health care:','["driver", "proxy", "vendor", "clerk"]'::jsonb,1,'Proxy acts for the patient.','original'),
('127.489.d.10.D',3,'When working with a patient who has a mental health condition, the medical assistant should respond in a calm and:','["rushed manner", "loud manner", "nonjudgmental manner", "sarcastic manner"]'::jsonb,2,'Respectful care.','original'),
('127.489.d.10.D',4,'If a patient says they are thinking of harming themselves, the medical assistant should:','["wait until the end of the day", "ignore it", "joke about it", "tell the provider immediately"]'::jsonb,3,'Safety concerns are urgent.','original'),
('127.489.d.10.E',3,'A patient who lacks reliable transportation may miss appointments, which is an example of how socioeconomic factors affect:','["access to care", "eye color", "hair color", "height"]'::jsonb,0,'Barriers affect health.','original'),
('127.489.d.10.E',4,'Lack of health insurance and low income are socioeconomic factors that can lead patients to delay:','["breathing", "preventive care", "sleeping", "blinking"]'::jsonb,1,'Costs delay care.','original'),
('127.489.d.10.F',3,'A patient from a culture that values family involvement may want relatives present for decisions, so the medical assistant should show:','["impatience", "stereotypes", "cultural sensitivity", "assumptions"]'::jsonb,2,'Respect values.','original'),
('127.489.d.10.F',4,'When an interpreter is needed, the medical assistant should use a trained interpreter rather than a:','["phone interpreter service", "certified professional", "staff interpreter", "family child"]'::jsonb,3,'Avoid using minors as interpreters.','original'),
('127.489.d.11.A',3,'Treating all blood and body fluids as if they could be infectious is the basis of standard:','["precautions", "billing", "coding", "scheduling"]'::jsonb,0,'Standard precautions protect all.','original'),
('127.489.d.11.A',4,'The single most important action for preventing the spread of infection is:','["using perfume", "hand hygiene", "opening windows", "wearing jewelry"]'::jsonb,1,'Hand hygiene prevents spread.','original'),
('127.489.d.11.B',3,'Malaria spread by the bite of an infected mosquito is an example of transmission by a:','["fomite", "droplet", "vector", "airborne cloud"]'::jsonb,2,'Vectors carry pathogens.','original'),
('127.489.d.11.B',4,'A doorknob that carries germs from one person to another is a(n):','["vector", "reservoir host", "carrier species", "fomite"]'::jsonb,3,'Fomites are contaminated objects.','original'),
('127.489.d.11.C',3,'A sign on a patient''s door that shows the room requires airborne precautions warns staff to wear a:','["N95 respirator", "scarf", "paper hat", "bandana"]'::jsonb,0,'N95 for airborne.','original'),
('127.489.d.11.C',4,'Contact precautions signage tells staff to wear a gown and:','["earplugs", "gloves", "a hat only", "sandals"]'::jsonb,1,'Gown and gloves for contact.','original'),
('127.489.d.11.D',3,'Gloves, masks, gowns, and face shields are all examples of:','["office supplies", "billing tools", "personal protective equipment", "medications"]'::jsonb,2,'PPE.','original'),
('127.489.d.11.D',4,'The purpose of eye protection such as goggles is to guard against:','["cold", "bright lights", "loud noise", "splashes of body fluids"]'::jsonb,3,'Eye protection prevents exposure.','original'),
('127.489.d.11.E',3,'During a blood draw, the medical assistant wears gloves and a:','["lab coat", "swimsuit", "raincoat", "apron for cooking"]'::jsonb,0,'Venipuncture requires gloves.','original'),
('127.489.d.11.E',4,'When a patient may cough or sneeze during a procedure, the medical assistant should add a:','["ring", "face mask", "watch", "scarf"]'::jsonb,1,'Droplet protection.','original'),
('127.489.d.11.F',3,'When putting on PPE, the correct first step is to perform:','["mask removal", "gown removal", "hand hygiene", "glove removal"]'::jsonb,2,'Start clean.','original'),
('127.489.d.11.F',4,'When doffing PPE, the item that is usually removed first is the:','["goggles", "hair cover", "mask", "gloves"]'::jsonb,3,'Gloves are most contaminated.','original'),
('127.489.d.11.G',3,'A rigid, puncture-resistant container for used needles is a:','["sharps container", "trash bag", "shredding bin", "paper box"]'::jsonb,0,'Sharps need special disposal.','original'),
('127.489.d.11.G',4,'Paper that contains patient information is disposed of in a:','["sink", "shredding bin", "hallway", "recycling bin"]'::jsonb,1,'Shredding protects privacy.','original'),
('127.489.d.11.H',3,'After giving an injection, a used needle should be placed in a sharps container without:','["labeling", "counting", "recapping", "weighing"]'::jsonb,2,'Never recap.','original'),
('127.489.d.11.H',4,'A sharps container should be replaced when it is about:','["one-fourth full", "empty", "painted", "three-fourths full"]'::jsonb,3,'Do not overfill.','original'),
('127.489.d.11.I',3,'A severe, life-threatening allergic reaction with swelling of the throat and trouble breathing is:','["anaphylaxis", "fever", "asthma only", "syncope"]'::jsonb,0,'Anaphylaxis is an emergency.','original'),
('127.489.d.11.I',4,'The first-line medication for anaphylaxis, often given with an auto-injector, is:','["acetaminophen", "epinephrine", "insulin", "penicillin"]'::jsonb,1,'Epinephrine reverses the reaction.','original'),
('127.489.d.11.J',3,'Vaccines and some medications must be stored in a refrigerator at 36 to 46 degrees:','["Rankine", "Kelvin", "Fahrenheit", "Celsius only"]'::jsonb,2,'2 to 8 C is 36 to 46 F.','original'),
('127.489.d.11.J',4,'A refrigerator used for vaccines should have its temperature recorded:','["once a decade", "once a year", "never", "every day"]'::jsonb,3,'Daily logs prevent spoilage.','original'),
('127.489.d.11.K',3,'A document that tells staff about the hazards of a chemical and first aid measures is a safety data sheet, abbreviated:','["SDS", "DEA", "CPT", "EHR"]'::jsonb,0,'SDS describes chemicals.','original'),
('127.489.d.11.K',4,'If bleach is splashed in the eye, the medical assistant should check the SDS and flush the eye with:','["oil", "water", "gel", "alcohol"]'::jsonb,1,'First aid for eye exposure.','original'),
('127.489.d.11.L',3,'Practices that reduce the number of germs but do not remove all microbes are called medical:','["sterility", "pathology", "asepsis", "surgery"]'::jsonb,2,'Medical asepsis is clean technique.','original'),
('127.489.d.11.L',4,'Washing hands and disinfecting an exam table between patients is an example of medical asepsis, which differs from surgical asepsis because it does not make the area completely:','["dry", "clean", "visible", "sterile"]'::jsonb,3,'Surgical asepsis is sterile.','original'),
('127.490.d.1.A',3,'A student reads a manual describing how a ventilator delivers breaths. Understanding it requires interpreting complex:','["technical material", "menus", "jokes", "comic strips"]'::jsonb,0,'Technical reading skills.','original'),
('127.490.d.1.A',4,'A respiratory therapist uses a device manual to find the settings for a nebulizer. The best way to interpret unfamiliar terms is to look them up in a:','["comic", "medical glossary", "menu", "novel"]'::jsonb,1,'Glossaries clarify terms.','original'),
('127.490.d.1.B',3,'A patient''s religious belief may influence whether they accept certain treatments, so the therapist should show:','["impatience", "dismissal", "respect for beliefs", "judgment"]'::jsonb,2,'Cultural competence.','original'),
('127.490.d.1.B',4,'A therapist caring for patients with different cultural backgrounds should ask each patient about their care:','["cars", "shoes", "birthdays", "preferences"]'::jsonb,3,'Ask about preferences.','original'),
('127.490.d.1.C',3,'A patient receives 40 percent oxygen. The percent of oxygen in room air is about:','["21 percent", "10 percent", "78 percent", "50 percent"]'::jsonb,0,'Room air is 21% O2.','original'),
('127.490.d.1.C',4,'A patient breathes 16 times per minute with a tidal volume of 500 mL. The minute ventilation is:','["32000 mL", "8000 mL", "516 mL", "800 mL"]'::jsonb,1,'16 x 500 = 8000 mL.','original'),
('127.490.d.1.D',3,'The body''s ability to keep its internal conditions stable is:','["digestion", "metamorphosis", "homeostasis", "hibernation"]'::jsonb,2,'Homeostasis maintains balance.','original'),
('127.490.d.1.D',4,'The lungs help regulate blood pH by removing carbon dioxide, which is part of the body''s acid-base:','["taste", "weight", "color", "balance"]'::jsonb,3,'CO2 affects pH.','original'),
('127.490.d.2.A',3,'The iron lung, used during polio epidemics, was an early form of:','["mechanical ventilation", "dialysis", "imaging", "anesthesia"]'::jsonb,0,'Iron lungs were early ventilators.','original'),
('127.490.d.2.A',4,'Modern ventilators have advanced from large negative-pressure tanks to computer-controlled machines that deliver:','["cold air", "positive pressure breaths", "suction only", "sound waves"]'::jsonb,1,'Positive pressure is current practice.','original'),
('127.490.d.2.B',3,'A respiratory therapist who works in a hospital''s intensive care unit might manage patients on a:','["treadmill", "bed lift only", "ventilator", "bicycle"]'::jsonb,2,'RTs manage ventilators.','original'),
('127.490.d.2.B',4,'Respiratory therapists may also work in home care, teaching patients to use oxygen equipment and:','["ovens", "televisions", "phones", "nebulizers"]'::jsonb,3,'Home care RTs educate.','original'),
('127.490.d.2.C',3,'Becoming a respiratory therapist typically requires at least an associate degree from an accredited:','["respiratory therapy program", "art program", "culinary program", "law school only"]'::jsonb,0,'Accredited program needed.','original'),
('127.490.d.2.C',4,'After graduating, a therapist earns the CRT credential by passing an exam given by the National Board for Respiratory:','["Cooking", "Care", "Cleaning", "Cars"]'::jsonb,1,'NBRC offers credentials.','original'),
('127.490.d.3.A',3,'The agency that sets and enforces workplace safety standards in hospitals is OSHA, which stands for the Occupational Safety and Health:','["Agreement", "Alliance", "Administration", "Association"]'::jsonb,2,'OSHA enforces standards.','original'),
('127.490.d.3.A',4,'The Joint Commission accredits hospitals and sets standards for patient:','["uniforms", "menus", "parking", "safety"]'::jsonb,3,'Accreditation standards.','original'),
('127.490.d.3.B',3,'Safety steps used for patients known to have a germ that spreads by respiratory droplets are called transmission-based:','["precautions", "recipes", "reports", "schedules"]'::jsonb,0,'Transmission-based precautions.','original'),
('127.490.d.3.B',4,'A patient with tuberculosis is placed in a negative-pressure room with airborne:','["decorations", "precautions", "menus", "visitors"]'::jsonb,1,'TB needs airborne precautions.','original'),
('127.490.d.3.C',3,'Using the legs instead of the back when lifting a heavy oxygen cylinder is proper body:','["painting", "art", "mechanics", "music"]'::jsonb,2,'Good body mechanics.','original'),
('127.490.d.3.C',4,'Oxygen cylinders should be secured upright with a chain or stand to prevent them from:','["changing color", "cooling", "rusting at night", "falling"]'::jsonb,3,'Cylinders are heavy and hazardous.','original'),
('127.490.d.4.A',3,'The heart chamber that pumps oxygen-rich blood to the body is the left:','["ventricle", "valve", "atrium", "vein"]'::jsonb,0,'Left ventricle pumps to the aorta.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
