from (values
('127.490.d.4.A',4,'The valve between the left atrium and the left ventricle is the:','["tricuspid valve", "mitral valve", "aortic valve", "pulmonary valve"]'::jsonb,1,'Mitral valve.','original'),
('127.490.d.4.B',3,'The windpipe that carries air from the larynx to the bronchi is the:','["esophagus", "alveolus", "trachea", "pharynx"]'::jsonb,2,'Trachea.','original'),
('127.490.d.4.B',4,'Gas exchange between air and blood takes place in tiny air sacs called:','["nephrons", "villi", "bronchi", "alveoli"]'::jsonb,3,'Alveoli exchange gases.','original'),
('127.490.d.4.C',3,'Blood from the body returns to the right atrium through the:','["vena cava", "aorta", "pulmonary vein", "carotid artery"]'::jsonb,0,'Vena cava returns blood.','original'),
('127.490.d.4.C',4,'After leaving the right ventricle, blood travels through the pulmonary artery to the:','["kidneys", "lungs", "liver", "brain"]'::jsonb,1,'Pulmonary circulation.','original'),
('127.490.d.4.D',3,'A chronic lung disease that includes emphysema and chronic bronchitis is:','["AIDS", "ALS", "COPD", "ADHD"]'::jsonb,2,'COPD obstructs airflow.','original'),
('127.490.d.4.D',4,'A heart condition in which the heart cannot pump enough blood to meet the body''s needs is:','["tonsillitis", "bronchitis", "appendicitis", "heart failure"]'::jsonb,3,'Heart failure reduces output.','original'),
('127.490.d.5.A',3,'A breathing exercise in which a patient inhales through the nose and exhales slowly through pursed lips is called:','["pursed-lip breathing", "breath holding", "hyperventilation", "gasping"]'::jsonb,0,'Pursed-lip slows breathing.','original'),
('127.490.d.5.A',4,'Deep breathing exercises using a device that shows how deeply a patient inhales are done with an incentive:','["otoscope", "spirometer", "stethoscope", "thermometer"]'::jsonb,1,'Spirometry encourages deep breaths.','original'),
('127.490.d.5.B',3,'Techniques such as chest physiotherapy and coughing exercises that help clear secretions are called airway clearance:','["recipes", "menus", "therapies", "tests"]'::jsonb,2,'Airway clearance.','original'),
('127.490.d.5.B',4,'Hyperinflation therapy uses deep breaths to help prevent collapse of the lungs, which is called:','["bronchitis", "pneumothorax", "asthma", "atelectasis"]'::jsonb,3,'Atelectasis is collapse.','original'),
('127.490.d.5.C',3,'A tube placed through the mouth into the windpipe to help a patient breathe is an:','["endotracheal tube", "chest tube", "IV tube", "feeding tube"]'::jsonb,0,'ET tube.','original'),
('127.490.d.5.C',4,'A surgical opening in the neck into the trachea for long-term breathing support is a:','["colostomy", "tracheostomy", "gastrostomy", "thoracotomy"]'::jsonb,1,'Tracheostomy.','original'),
('127.490.d.5.D',3,'The tip of an endotracheal tube should sit above the carina, which is where the trachea divides into the:','["pulmonary veins", "alveoli", "main bronchi", "lung lobes"]'::jsonb,2,'Proper ET position.','original'),
('127.490.d.5.D',4,'The best way to confirm endotracheal tube position after placement is to check a chest:','["hearing test", "scale", "thermometer", "X-ray"]'::jsonb,3,'X-ray confirms position.','original'),
('127.490.d.5.E',3,'A small device clipped to a fingertip that measures the percent of oxygen in the blood is a pulse:','["oximeter", "sphygmomanometer", "glucometer", "thermometer"]'::jsonb,0,'Pulse oximeter.','original'),
('127.490.d.5.E',4,'A blood sample taken from an artery to measure oxygen, carbon dioxide, and pH is an arterial blood:','["culture", "gas", "count", "type"]'::jsonb,1,'ABG.','original'),
('127.490.d.5.F',3,'A low-flow device that delivers oxygen through two small prongs in the nostrils is a nasal:','["mask", "hood", "cannula", "tent"]'::jsonb,2,'Nasal cannula.','original'),
('127.490.d.5.F',4,'A device with a reservoir bag that covers the nose and mouth and delivers a high concentration of oxygen is a non-rebreather:','["helmet only", "tent", "cannula", "mask"]'::jsonb,3,'Non-rebreather.','original'),
('127.490.d.5.G',3,'A machine that takes oxygen from room air and concentrates it for home use is an oxygen:','["concentrator", "humidifier", "regulator", "cylinder"]'::jsonb,0,'Concentrator.','original'),
('127.490.d.5.G',4,'Oxygen is a fire hazard, so patients using it must not be near open flames or:','["television", "smoking", "books", "music"]'::jsonb,1,'No smoking.','original'),
('127.490.d.6.A',3,'A medication that relaxes airway muscles and opens the airways is a:','["antibiotic", "diuretic", "bronchodilator", "anticoagulant"]'::jsonb,2,'Bronchodilators open airways.','original'),
('127.490.d.6.A',4,'Albuterol is a short-acting bronchodilator commonly used as a:','["antibiotic", "daily vitamin", "sleep aid", "rescue inhaler"]'::jsonb,3,'Albuterol relieves symptoms.','original'),
('127.490.d.6.B',3,'A common side effect of albuterol is a fast heart rate, also known as:','["tachycardia", "bradycardia", "hypothermia", "hypotension"]'::jsonb,0,'Beta agonists raise heart rate.','original'),
('127.490.d.6.B',4,'Inhaled corticosteroids can cause a fungal infection of the mouth called:','["measles", "thrush", "strep", "mumps"]'::jsonb,1,'Rinse after use.','original'),
('127.490.d.6.C',3,'A device that turns liquid medicine into a fine mist for inhalation is a:','["syringe", "scalpel", "nebulizer", "tourniquet"]'::jsonb,2,'Nebulizer.','original'),
('127.490.d.6.C',4,'A metered-dose inhaler delivers each dose from a pressurized canister, and a spacer is used to improve:','["cost", "color", "flavor", "drug delivery to the lungs"]'::jsonb,3,'Spacers help delivery.','original'),
('127.490.d.6.D',3,'Beta agonists can increase a patient''s heart rate and:','["blood pressure", "weight loss", "height", "hair growth"]'::jsonb,0,'Vital signs change.','original'),
('127.490.d.6.D',4,'After giving a bronchodilator, a respiratory therapist rechecks the patient''s heart rate and:','["insurance", "breath sounds", "height", "shoe size"]'::jsonb,1,'Assess response.','original'),
('127.490.d.7.A',3,'The vital sign that shows how fast the heart beats is the:','["temperature", "height", "pulse", "weight"]'::jsonb,2,'Pulse = heart rate.','original'),
('127.490.d.7.A',4,'A respiratory therapist counts respirations for a full minute without letting the patient know, to avoid changing the:','["weight", "blood type", "height", "breathing pattern"]'::jsonb,3,'Patients alter breathing when watched.','original'),
('127.490.d.7.B',3,'A position with the head of the bed raised 45 to 90 degrees to ease breathing is the:','["Fowler''s position", "supine position", "prone position", "Trendelenburg position"]'::jsonb,0,'Fowler''s helps breathing.','original'),
('127.490.d.7.B',4,'A patient lying flat on the back is in the supine position, while a patient lying on the stomach is in the:','["sitting position", "prone position", "lateral position", "Fowler''s position"]'::jsonb,1,'Prone = face down.','original'),
('127.490.d.7.C',3,'During a cardiac arrest, the respiratory therapist''s role may include providing:','["scheduling", "billing", "ventilation", "filing"]'::jsonb,2,'RTs manage airway.','original'),
('127.490.d.7.C',4,'In a high-stress situation such as a code, the respiratory therapist keeps calm and uses clear, closed-loop:','["music", "silence", "jokes", "communication"]'::jsonb,3,'Closed-loop communication.','original'),
('127.490.d.7.D',3,'For adult CPR, chest compressions are done at a rate of 100 to 120 per minute at a depth of at least:','["2 inches", "5 inches", "half an inch", "1 inch"]'::jsonb,0,'At least 2 inches.','original'),
('127.490.d.7.D',4,'An automated external defibrillator is used to analyze the heart rhythm and deliver a shock when needed. It is abbreviated:','["EKG", "AED", "MRI", "CPR"]'::jsonb,1,'AED.','original'),
('127.490.d.7.E',3,'Speaking in a calm tone and giving simple explanations to an anxious patient is therapeutic:','["delay", "avoidance", "communication", "argument"]'::jsonb,2,'Therapeutic communication.','original'),
('127.490.d.7.E',4,'A therapist who says, ''Tell me more about how you''re feeling'' is using an:','["closed question", "command", "yes/no question", "open-ended question"]'::jsonb,3,'Open-ended invites detail.','original'),
('127.490.d.8.A',3,'The ethical principle that a patient has the right to make their own choices about care is:','["autonomy", "beneficence", "justice", "fidelity"]'::jsonb,0,'Autonomy.','original'),
('127.490.d.8.A',4,'A patient''s right to refuse a treatment is protected by the Patient''s:','["Menu", "Bill of Rights", "Newsletter", "Calendar"]'::jsonb,1,'Rights include refusal.','original'),
('127.490.d.8.B',3,'Falsifying a patient''s record is unacceptable behavior that can lead to loss of a professional:','["parking", "uniform", "license", "lunch"]'::jsonb,2,'Falsification has penalties.','original'),
('127.490.d.8.B',4,'Sharing a patient''s information on social media violates:','["OSHA", "FDA", "ADA", "HIPAA"]'::jsonb,3,'Privacy law.','original'),
('127.490.d.8.C',3,'The professional organization for respiratory therapists in the United States is the American Association for Respiratory:','["Care", "Classes", "Cooking", "Cars"]'::jsonb,0,'AARC.','original'),
('127.490.d.8.C',4,'A state board that licenses respiratory therapists to practice is a regulatory:','["club", "agency", "team", "band"]'::jsonb,1,'State licensure.','original'),
('127.490.d.8.D',3,'A patient with a terminal illness refuses a ventilator. The therapist faces an ethical dilemma between respecting autonomy and the duty to:','["finish work", "save time", "preserve life", "reduce cost"]'::jsonb,2,'Ethical dilemma.','original'),
('127.490.d.8.D',4,'A do-not-resuscitate order means that CPR should not be performed if the patient''s:','["room is cold", "bill is high", "name changes", "heart stops"]'::jsonb,3,'DNR.','original'),
('127.491.d.1.A',3,'A therapist reviews a research article on high-flow oxygen therapy. Evaluating how well the study was designed is part of analyzing complex technical:','["material", "menus", "songs", "recipes"]'::jsonb,0,'Technical analysis.','original'),
('127.491.d.1.A',4,'When two journal articles give different results for a ventilator strategy, the therapist should compare the study methods and sample:','["fonts", "sizes", "colors", "titles"]'::jsonb,1,'Compare methods.','original'),
('127.491.d.1.B',3,'A therapist who learns that a patient''s language is not English should arrange for a qualified:','["mascot", "gift", "interpreter", "map"]'::jsonb,2,'Interpreters support care.','original'),
('127.491.d.1.B',4,'Religious beliefs that forbid certain blood products affect how a therapist plans the patient''s:','["uniform", "parking", "lunch", "care"]'::jsonb,3,'Beliefs shape care.','original'),
('127.491.d.1.C',3,'A patient''s tidal volume is 450 mL and the respiratory rate is 20. The minute ventilation is:','["9000 mL", "4500 mL", "900 mL", "470 mL"]'::jsonb,0,'450 x 20 = 9000.','original'),
('127.491.d.1.C',4,'A patient needs a FiO2 of 0.4. As a percentage, this is:','["4 percent", "40 percent", "400 percent", "0.4 percent"]'::jsonb,1,'0.4 = 40%.','original'),
('127.491.d.1.D',3,'Carbon dioxide dissolved in blood forms carbonic acid, so a rise in CO2 makes the blood more:','["sweet", "salty", "acidic", "basic"]'::jsonb,2,'CO2 lowers pH.','original'),
('127.491.d.1.D',4,'Breathing too fast blows off carbon dioxide and can cause the blood to become too:','["acidic", "warm", "thick", "alkaline"]'::jsonb,3,'Hyperventilation raises pH.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
